// Map n8n Form Trigger field labels to internal variable names.
// Also accepts a raw JSON body so the workflow can be tested via the n8n manual trigger.
const data = $input.first().json;

const topic         = (data['Topic or Industry'] || data.topic         || '').trim();
const keyword       = (data['Keyword']            || data.keyword       || '').trim();
const clientWebsite = (data['Client Website']     || data.clientWebsite || '').trim();
const audience      = (data['Audience']           || data.audience      || '').trim();
const providerRaw   = (data['AI Provider']        || data.provider      || 'Claude (Anthropic)').trim();

// Map dropdown label → internal provider key
const provider = providerRaw.toLowerCase().includes('openai') ? 'openai' : 'anthropic';

if (!topic)   throw new Error('Topic or Industry is required');
if (!keyword) throw new Error('Keyword is required');

return [{ json: { topic, keyword, audience, clientWebsite, provider } }];

// Runs 5 Serper searches + homepage fetch in parallel.
// Set SERPER_API_KEY in n8n: Settings → Environment Variables.
const { topic, keyword, audience, clientWebsite, provider } = $input.first().json;
const SERPER_KEY = $env.SERPER_API_KEY;

const queries = [
  { source: 'Reddit',     query: `site:reddit.com "${topic}" "${keyword}" B2B OR software OR tool` },
  { source: 'G2',         query: `site:g2.com/reviews "${topic}" "${keyword}"` },
  { source: 'Capterra',   query: `site:capterra.com "${topic}" "${keyword}"` },
  { source: 'Trustpilot', query: `site:trustpilot.com "${topic}" "${keyword}"` },
  { source: 'Forum',      query: `"${topic}" "${keyword}" community OR forum questions pain points` },
];

async function serperSearch(query, source) {
  try {
    const res = await fetch('https://google.serper.dev/search', {
      method: 'POST',
      headers: { 'X-API-KEY': SERPER_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ q: query, num: 3 }),
    });
    const data = await res.json();
    return (data.organic || []).slice(0, 3).map(r => ({
      title:   r.title   || '',
      snippet: r.snippet || '',
      source,
    }));
  } catch {
    return [];
  }
}

async function fetchWebsite(url) {
  if (!url) return null;
  try {
    const res = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; IntentSpymasterBot/1.0)',
        'Accept': 'text/html',
      },
    });
    if (!res.ok) return null;
    return await res.text();
  } catch {
    return null;
  }
}

const [snippetGroups, websiteHtml] = await Promise.all([
  Promise.all(queries.map(({ query, source }) => serperSearch(query, source))),
  fetchWebsite(clientWebsite),
]);

const snippets = snippetGroups.flat().slice(0, 15);

return [{ json: { topic, keyword, audience, clientWebsite, provider, snippets, websiteHtml } }];

// Strips HTML tags from the fetched homepage, then asks the selected AI
// to extract purpose / personas / problems. Skips silently if no URL was provided.
const { topic, keyword, audience, clientWebsite, provider, snippets, websiteHtml } = $input.first().json;

function extractTextFromHTML(html) {
  if (!html) return null;
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 3000);
}

async function callAI(prompt, provider, maxTokens) {
  if (provider === 'openai') {
    const res = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${$env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'gpt-4o', max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message);
    return data.choices[0].message.content;
  } else {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message);
    return data.content[0].text;
  }
}

function parseJSON(raw) {
  return JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim());
}

const websiteText = extractTextFromHTML(websiteHtml);
let clientContext = null;

if (websiteText) {
  const prompt = `You are a B2B positioning analyst. Read the website copy below and extract a concise understanding of this company.

Return ONLY a valid JSON object — no explanation, no markdown, no preamble.

Format:
{
  "purpose": "1-2 sentences: what they do, what gap they fill, what makes them unique",
  "personas": "1-2 sentences: who their main target audiences or buyers are",
  "problems": "1-2 sentences: the core pains or challenges they solve for those personas"
}

Rules:
- Be specific — avoid generic filler like "we help businesses grow"
- If a field cannot be determined, write "Not clear from website"
- Keep each field to 1-2 sentences maximum

Website copy:
${websiteText}`;

  try {
    const raw = await callAI(prompt, provider, 512);
    clientContext = parseJSON(raw);
  } catch {
    // silently degrade — research continues without client context
  }
}

return [{ json: { topic, keyword, audience, clientWebsite, provider, snippets, clientContext } }];

// Builds the master intent prompt, calls the selected AI, and parses the signal array.
const { topic, keyword, audience, provider, snippets, clientContext } = $input.first().json;

if (!snippets || snippets.length === 0) {
  throw new Error('No snippets found — try a broader topic or keyword.');
}

async function callAI(prompt, provider, maxTokens) {
  if (provider === 'openai') {
    const res = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${$env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'gpt-4o', max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message);
    return data.choices[0].message.content;
  } else {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1024, messages: [{ role: 'user', content: prompt }] }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message);
    return data.content[0].text;
  }
}

const audienceClause = audience
  ? `\nAudience filter: Focus signals relevant to "${audience}". Deprioritize signals not applicable to this persona.`
  : '';

const clientClause = clientContext
  ? `\nClient context (prioritise signals this client could credibly address):\n- Purpose: ${clientContext.purpose}\n- Serves: ${clientContext.personas}\n- Solves: ${clientContext.problems}`
  : '';

const formattedSnippets = snippets
  .map((s, i) => `[${i + 1}] Source: ${s.source}\nTitle: ${s.title}\nSnippet: ${s.snippet}`)
  .join('\n\n');

const prompt = `You are a B2B content strategist helping writers understand real audience intent.

Below are search result snippets about "${topic}" (keyword: "${keyword}"). Extract genuine user intent signals a writer could use to create better B2B content.${audienceClause}${clientClause}

Rules:
- Only extract signals present in the snippets. Do not invent or infer beyond what is written.
- Focus on signals relevant to a B2B audience (buyers, practitioners, decision-makers).
- Skip consumer-only content, spam, or irrelevant results.
- If client context is provided, deprioritise signals unrelated to what the client does.
- Write each signal as a clear, natural statement or question (1-2 sentences max).
- Return a maximum of 15 signals total.

Assign each signal one category:
- Question — something users are actively trying to figure out
- Pain Point — a frustration, failure, or unmet need
- Comparison — evaluating options, switching decisions, or vendor comparisons
- Anecdote — a personal story or real-world use case
- Feature Request — something users wish a product or solution would do

Return ONLY a valid JSON array. No explanation, no markdown, no preamble.

Format:
[
  {
    "signal": "...",
    "category": "Pain Point",
    "source": "Reddit"
  }
]

Snippets:
${formattedSnippets}`;

const raw = await callAI(prompt, provider, 1024);
const signals = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim());

return [{ json: { signals, clientContext, snippetCount: snippets.length, topic, keyword, provider } }];

// Builds a self-contained HTML results page returned directly to the browser.
const { signals, clientContext, snippetCount, topic, keyword, provider } = $input.first().json;

const CATEGORY_ORDER = ['Question', 'Pain Point', 'Comparison', 'Anecdote', 'Feature Request'];
const CATEGORY_COLORS = {
  'Question':        '#4f7ef8',
  'Pain Point':      '#e05c5c',
  'Comparison':      '#f0964a',
  'Anecdote':        '#7c5cbf',
  'Feature Request': '#27ae7a',
};
const SOURCE_COLORS = {
  'Reddit': '#ff4500', 'G2': '#ff492c', 'Capterra': '#00a2e8',
  'Trustpilot': '#00b67a', 'Forum': '#7c5cbf',
};
const PROVIDER_LABELS = { anthropic: 'Claude', openai: 'ChatGPT' };

// Group signals by category
const grouped = {};
for (const cat of CATEGORY_ORDER) grouped[cat] = [];
for (const s of (signals || [])) {
  const cat = grouped[s.category] ? s.category : 'Question';
  grouped[cat].push(s);
}

// Escape HTML special characters to prevent XSS in the output page
function esc(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Build category blocks
let categoriesHtml = '';
for (const cat of CATEGORY_ORDER) {
  const items = grouped[cat];
  if (!items.length) continue;
  const color = CATEGORY_COLORS[cat] || '#888';
  const rows = items.map(s => {
    const srcColor = SOURCE_COLORS[s.source] || '#888';
    return `<li class='si'><span class='src' style='background:${srcColor}'>${esc(s.source)}</span><span class='st'>${esc(s.signal)}</span></li>`;
  }).join('');
  categoriesHtml += `<div class='cb' style='border-left-color:${color}'><h3 class='ch' style='color:${color}'>${esc(cat)} <span class='cn'>${items.length}</span></h3><ul class='sl'>${rows}</ul></div>`;
}

// Build client context block
let clientHtml = '';
if (clientContext) {
  clientHtml = `<div class='cc'>
    <p class='cl'>Client Understanding</p>
    <div class='cr'><span class='ck'>Purpose</span><p>${esc(clientContext.purpose)}</p></div>
    <div class='cr'><span class='ck'>Personas</span><p>${esc(clientContext.personas)}</p></div>
    <div class='cr'><span class='ck'>Problems</span><p>${esc(clientContext.problems)}</p></div>
  </div>`;
}

const providerLabel = PROVIDER_LABELS[provider] || provider;

const html = `<!DOCTYPE html>
<html lang='en'>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>Intent Signals — ${esc(topic)}</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f8f9fb;color:#1a1a2e;padding:32px 16px 64px;line-height:1.5}
.wrap{max-width:700px;margin:0 auto}
.logo{font-size:12px;color:#9ca3af;letter-spacing:.06em;margin-bottom:10px}
h1{font-size:22px;font-weight:800;margin-bottom:10px}
.chips{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:28px}
.chip{background:#fff;border:1px solid #e4e7ed;border-radius:20px;padding:3px 10px;font-size:12px;color:#6b7280}
.cc{background:#fff;border:1px solid #e4e7ed;border-left:4px solid #4f7ef8;border-radius:10px;padding:16px 18px;margin-bottom:14px}
.cl{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#4f7ef8;margin-bottom:10px}
.cr{margin-bottom:8px}.cr:last-child{margin-bottom:0}
.ck{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;display:block;margin-bottom:2px}
.cr p{font-size:13px;line-height:1.5;color:#1a1a2e}
.cb{background:#fff;border:1px solid #e4e7ed;border-left:4px solid #888;border-radius:10px;padding:16px 18px;margin-bottom:12px}
.ch{font-size:14px;font-weight:700;margin-bottom:12px;display:flex;align-items:center;gap:8px}
.cn{background:#f8f9fb;border:1px solid #e4e7ed;border-radius:12px;padding:1px 8px;font-size:12px;color:#6b7280;font-weight:400}
.sl{list-style:none}
.si{display:flex;align-items:flex-start;gap:10px;padding:9px 0;border-bottom:1px solid #f0f2f5}
.si:last-child{border-bottom:none;padding-bottom:0}
.src{flex-shrink:0;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:700;color:#fff;margin-top:3px;white-space:nowrap}
.st{font-size:13px;line-height:1.5;color:#1a1a2e}
.foot{margin-top:28px;font-size:11px;color:#d1d5db;text-align:center}
</style>
</head>
<body>
<div class='wrap'>
  <p class='logo'>◈ INTENT SPYMASTER</p>
  <h1>${esc(topic)}</h1>
  <div class='chips'>
    <span class='chip'>${signals.length} signals</span>
    <span class='chip'>${snippetCount} sources scanned</span>
    <span class='chip'>keyword: ${esc(keyword)}</span>
    <span class='chip'>via ${providerLabel}</span>
  </div>
  ${clientHtml}
  ${categoriesHtml}
  <p class='foot'>Generated by Intent Spymaster &middot; Signals filtered to B2B relevance</p>
</div>
</body>
</html>`;

return [{ json: { html } }];
